#!/bin/bash
sed -i 's/import com.example.data.sources.VideoStreamInfo/import com.example.data.sources.VideoStreamInfo\nimport java.io.File\nimport com.example.data.db.DownloadDao/g' app/src/main/java/com/example/ui/viewmodels/PlayerViewModel.kt

sed -i 's/private val settingsManager: com.example.data.SettingsManager/private val settingsManager: com.example.data.SettingsManager,\n    private val downloadDao: DownloadDao,\n    private val context: android.content.Context/g' app/src/main/java/com/example/ui/viewmodels/PlayerViewModel.kt

sed -i 's/private fun loadVideo() {/private fun loadVideo() {\n        viewModelScope.launch {\n            _streamInfo.value = PlayerState.Loading\n            try {\n                val download = downloadDao.getDownload(sourceId, itemId, _currentEpisodeId.value)\n                if (download != null \&\& download.state == "DOWNLOADED") {\n                    val file = File(context.filesDir, "downloads/$sourceId/$itemId/${_currentEpisodeId.value}/video.mp4")\n                    if (file.exists()) {\n                        _streamInfo.value = PlayerState.Success(VideoStreamInfo(_currentEpisodeId.value, embedUrl = "file://${file.absolutePath}"))\n                        return@launch\n                    }\n                }\n                repository.getVideoStream(_currentEpisodeId.value, sourceId).collect { info ->\n                    _streamInfo.value = PlayerState.Success(info)\n                }\n                if (_streamInfo.value is PlayerState.Loading) {\n                    repository.getVideoStreamUrl(_currentEpisodeId.value, sourceId).collect { url ->\n                        _streamInfo.value = PlayerState.Success(VideoStreamInfo(_currentEpisodeId.value, embedUrl = url))\n                    }\n                }\n            } catch (e: CancellationException) {\n                throw e\n            } catch (e: Exception) {\n                _streamInfo.value = PlayerState.Error(e.message ?: "Failed to load video")\n            }\n        }\n    }\n\n    private fun loadVideoOld() {/g' app/src/main/java/com/example/ui/viewmodels/PlayerViewModel.kt

